SINA_SMART["fa-bleeding"] = {"lecture":"fa-bleeding","title":"Bleeding","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"fa-bleeding:e0","text":"Loss of more than 25% of blood volume can cause shock.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"fa-bleeding:e3","text":"Steps: direct pressure, then packing, then tourniquet.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"fa-bleeding:e4","text":"Tourniquet: last resort for massive limb bleeding.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"fa-bleeding:e1","text":"Think of internal as well as external bleeding.","topic":"Assess the bleeding","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"fa-bleeding:e2","text":"Check inside bulky clothing and under the patient.","topic":"Assess the bleeding","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"fa-bleeding:s2","text":"Describe and explain: Care: pressure and packing","topic":"Care: pressure and packing","sec":2,"importance":"standard","highYield":"insufficient-source"},{"id":"fa-bleeding:e5","text":"Band 7.5 to 10 cm, wide and flat, never wire or rope.","topic":"Tourniquet","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"fa-bleeding:e6","text":"Place as close above the wound as possible.","topic":"Tourniquet","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"fa-bleeding:e7","text":"Note the time of application.","topic":"Tourniquet","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"fa-bleeding:e8","text":"Over 1 hour from care: loosen slowly at 60 min while pressing.","topic":"Tourniquet","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"fa-bleeding:e9","text":"Commercial tourniquets: CAT, SOFT.","topic":"Tourniquet","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"fa-bleeding:e10","text":"Pelvic sling centred on the greater trochanters.","topic":"Pelvic sling","sec":4,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"1mrcr1u":"a","1piem7y":"a","9ixl61":"a","1a01ie9":"a","gte0kp":"a","14jyjxd":"a","3nsmrm":"a","jrhgs2":"a","114ktn3":"a","qpc8z":"a","1srn5cf":"a","b2q04y":"a","1tdv0nf":"a","wfbu7q":"a","m67w37":"a","1j7uqgk":"a","16cwduf":"a","l34qmx":"a","1f4qvn4":"a","1b9bz2y":"a"},"mapCounts":{"verified":0,"auto":20,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"fa-bleeding:e0":{"s":0,"u":["Loss of more than 25% of blood volume can cause shock.","A victim who loses more than 25% of their blood volume may develop shock."],"dp":[]},"fa-bleeding:e3":{"s":0,"u":["Steps: direct pressure, then packing, then tourniquet.","Stop bleeding in steps: direct pressure , then wound packing , then a tourniquet for massive limb bleeding."],"dp":[{"h":"Why width matters for a tourniquet","t":"A narrow cord concentrates force on a thin strip of skin: it cuts and crushes nerves and muscle before it squeezes the artery shut. A band 7.5 to 10 cm wide spreads the same pressure over a larger area, closing the artery at lower pressure with less tissue damage. Source: the lecture's tourniquet application slide."}]},"fa-bleeding:e4":{"s":0,"u":["Tourniquet: last resort for massive limb bleeding.","Stop bleeding in steps: direct pressure , then wound packing , then a tourniquet for massive limb bleeding."],"dp":[]},"fa-bleeding:e1":{"s":1,"u":["Think of internal as well as external bleeding.","Ask where the bleeding is (think of internal as well as external), whether it is arterial or venous , and whether more than 25% of blood volume may be lost."],"dp":[]},"fa-bleeding:e2":{"s":1,"u":["Check inside bulky clothing and under the patient.","Check carefully for profuse bleeding, feeling inside bulky clothing and underneath the patient ."],"dp":[]},"fa-bleeding:s2":{"s":2,"u":["Protect yourself (gloves), call the EMS, then apply a dressing and press .","For deep wounds, pack the wound with gauze to press directly on the bleeding source."],"dp":[]},"fa-bleeding:e5":{"s":3,"u":["Band 7.5 to 10 cm, wide and flat, never wire or rope.","How : wide, flat, non-stretch band 7.5 to 10 cm (never wire or rope); wrap several times as close above the wound as possible ; overhand knot, stick on the knot, second knot; twist until bleeding stops; tie or tape the stick; note the time ."],"dp":[]},"fa-bleeding:e6":{"s":3,"u":["Place as close above the wound as possible.","How : wide, flat, non-stretch band 7.5 to 10 cm (never wire or rope); wrap several times as close above the wound as possible ; overhand knot, stick on the knot, second knot; twist until bleeding stops; tie or tape the stick; note the time .","More than an hour from care: loosen very slowly at 60 minutes while pressing the wound; retighten if heavy bleeding returns; if manageable, leave it loose in place."],"dp":[]},"fa-bleeding:e7":{"s":3,"u":["Note the time of application.","How : wide, flat, non-stretch band 7.5 to 10 cm (never wire or rope); wrap several times as close above the wound as possible ; overhand knot, stick on the knot, second knot; twist until bleeding stops; tie or tape the stick; note the time ."],"dp":[]},"fa-bleeding:e8":{"s":3,"u":["Over 1 hour from care: loosen slowly at 60 min while pressing.","More than an hour from care: loosen very slowly at 60 minutes while pressing the wound; retighten if heavy bleeding returns; if manageable, leave it loose in place."],"dp":[]},"fa-bleeding:e9":{"s":3,"u":["Commercial tourniquets: CAT, SOFT.","Rescue teams should carry commercial models such as the CAT (Combat Application Tourniquet) or SOFT ; improvised ones can be made from clothing, towels or tent material."],"dp":[]},"fa-bleeding:e10":{"s":4,"u":["Pelvic sling centred on the greater trochanters.","For pelvic trauma: remove belts and pocket items; slide the improvised material under the buttocks and centre it on the greater trochanters ; cross it over the front of the pelvis, pull both ends and secure with a knot, clamp or duct tape."],"dp":[{"h":"Why a sling helps a broken pelvis","t":"An open-book pelvic fracture enlarges the pelvic volume, and torn pelvic veins can lose litres of blood into that space. Binding the pelvis at the level of the greater trochanters closes the ring, reduces the volume the blood can fill and brings the bone ends together, which helps the bleeding stop. Source: the lecture's pelvic sling slides."}]}},"meta":{"1mrcr1u":{"a":"recall","vg":"fa-bleeding:e0/recall/1"},"1piem7y":{"a":"recall","vg":"fa-bleeding:e3/recall/1"},"9ixl61":{"a":"recall","vg":"fa-bleeding:e4/recall/1"},"1a01ie9":{"a":"recall","vg":"fa-bleeding:e5/recall/1"},"gte0kp":{"a":"recall","vg":"fa-bleeding:e3/recall/2"},"14jyjxd":{"a":"recall","vg":"fa-bleeding:e7/recall/1"},"3nsmrm":{"a":"recall","vg":"fa-bleeding:e9/recall/1"},"jrhgs2":{"a":"recall","vg":"fa-bleeding:e10/recall/1"},"114ktn3":{"a":"recall","vg":"fa-bleeding:e10/recall/2"},"qpc8z":{"a":"recall","vg":"fa-bleeding:e1/recall/1"},"1srn5cf":{"a":"recall","vg":"fa-bleeding:e5/recall/1"},"b2q04y":{"a":"recall","vg":"fa-bleeding:e2/recall/1"},"1tdv0nf":{"a":"recall","vg":"fa-bleeding:e3/recall/3"},"wfbu7q":{"a":"recall","vg":"fa-bleeding:e5/recall/1"},"m67w37":{"a":"recall","vg":"fa-bleeding:e6/recall/1"},"1j7uqgk":{"a":"recall","vg":"fa-bleeding:e7/recall/2"},"16cwduf":{"a":"application","vg":"fa-bleeding:e8/application/1"},"l34qmx":{"a":"recall","vg":"fa-bleeding:e9/recall/2"},"1f4qvn4":{"a":"recall","vg":"fa-bleeding:e10/recall/2"},"1b9bz2y":{"a":"recall","vg":"fa-bleeding:e10/recall/3"}},"explRev":"f6c33690a314"};
